class Solution {
    private char[] norm(String s) {
        char[] c = s.replace(" ", "").toLowerCase().toCharArray();
        Arrays.sort(c);
        return c;
    }

    public boolean isScramble(String a, String b) {
        return Arrays.equals(norm(a), norm(b));
    }
}

