class Solution {
    static string norm(const string& s) {
        string out;
        for (char c : s) if (c != ' ') out += tolower((unsigned char) c);
        sort(out.begin(), out.end());
        return out;
    }

public:
    bool isScramble(string& a, string& b) {
        return norm(a) == norm(b);
    }
};

