#include <ctype.h>

static int cmp_char(const void* x, const void* y) { return *(const char*) x - *(const char*) y; }

static char* norm(const char* s) {
    char* out = malloc(strlen(s) + 1);
    int w = 0;
    for (; *s; s++) if (*s != ' ') out[w++] = tolower((unsigned char) *s);
    out[w] = '\0';
    qsort(out, w, 1, cmp_char);
    return out;
}

bool isScramble(char* a, char* b) {
    char *x = norm(a), *y = norm(b);
    bool same = strcmp(x, y) == 0;
    free(x); free(y);
    return same;
}

