class Solution:
    def isScramble(self, a: str, b: str) -> bool:
        cnt = [0] * 26
        for c in a:
            if c != " ":
                cnt[ord(c.lower()) - 97] += 1
        for c in b:
            if c != " ":
                cnt[ord(c.lower()) - 97] -= 1
        return not any(cnt)

