class Solution {
    public boolean isScramble(String a, String b) {
        int[] cnt = new int[26];
        for (char c : a.toCharArray()) if (c != ' ') cnt[Character.toLowerCase(c) - 'a']++;
        for (char c : b.toCharArray()) if (c != ' ') cnt[Character.toLowerCase(c) - 'a']--;
        for (int x : cnt) if (x != 0) return false;
        return true;
    }
}

