bool isScramble(char* a, char* b) {
    int cnt[26] = {0};
    for (; *a; a++) if (*a != ' ') cnt[tolower((unsigned char) *a) - 'a']++;
    for (; *b; b++) if (*b != ' ') cnt[tolower((unsigned char) *b) - 'a']--;
    for (int x = 0; x < 26; x++) if (cnt[x]) return false;
    return true;
}
